#!/usr/bin/env python3

import sys
import os

# Add the src directory to the path so we can import flask
sys.path.insert(0, os.path.join(os.path.dirname(__file__), 'src'))

from flask import Blueprint

def test_empty_name_validation():
    """Test that creating a Blueprint with an empty name raises ValueError"""
    try:
        # This should raise a ValueError
        bp = Blueprint("", __name__)
        print("ERROR: Blueprint with empty name was created successfully - this should not happen!")
        return False
    except ValueError as e:
        if "Blueprint name cannot be empty" in str(e):
            print("SUCCESS: Blueprint with empty name correctly raised ValueError:", str(e))
            return True
        else:
            print("ERROR: ValueError raised but with wrong message:", str(e))
            return False
    except Exception as e:
        print("ERROR: Unexpected exception raised:", type(e).__name__, str(e))
        return False

def test_normal_name_still_works():
    """Test that creating a Blueprint with a normal name still works"""
    try:
        bp = Blueprint("test_blueprint", __name__)
        print("SUCCESS: Blueprint with normal name created successfully")
        return True
    except Exception as e:
        print("ERROR: Blueprint with normal name failed:", type(e).__name__, str(e))
        return False

def test_dot_validation_still_works():
    """Test that the existing dot validation still works"""
    try:
        bp = Blueprint("test.blueprint", __name__)
        print("ERROR: Blueprint with dot in name was created - this should not happen!")
        return False
    except ValueError as e:
        if "may not contain a dot" in str(e):
            print("SUCCESS: Blueprint with dot in name correctly raised ValueError:", str(e))
            return True
        else:
            print("ERROR: ValueError raised but with wrong message:", str(e))
            return False
    except Exception as e:
        print("ERROR: Unexpected exception raised:", type(e).__name__, str(e))
        return False

if __name__ == "__main__":
    print("Testing Blueprint name validation...")

    tests = [
        test_empty_name_validation,
        test_normal_name_still_works,
        test_dot_validation_still_works
    ]

    results = []
    for test in tests:
        print(f"\nRunning {test.__name__}...")
        results.append(test())

    print(f"\nResults: {sum(results)}/{len(results)} tests passed")

    if all(results):
        print("All tests passed!")
        sys.exit(0)
    else:
        print("Some tests failed!")
        sys.exit(1)
